parameters.jsonBody:
={{ JSON.stringify({
  parent: { database_id: $('Config').first().json.notion_events_db },
  properties: {
    Name: { title: [{ text: { content: String($('Error Trigger').first().json.workflow.name + ' failed').slice(0, 200) } }] },
    Workflow: { select: { name: 'Error Handler' } },
    Step: { select: { name: 'error' } },
    Result: { select: { name: 'error' } },
    Detail: { rich_text: [{ text: { content: String('workflow=' + $('Error Trigger').first().json.workflow.name + ' | node=' + ($('Error Trigger').first().json.execution.lastNodeExecuted || '?') + ' | ' + ($('Error Trigger').first().json.execution.error.message || 'no message') + ' | ' + ($('Error Trigger').first().json.execution.url || '')).slice(0, 1900) } }] },
    Timestamp: { date: { start: $now.toISO() } },
    'Run ID': { rich_text: [{ text: { content: String($execution.id) } }] },
    'Envelope ID': { rich_text: [{ text: { content: String('' || '') } }] },
    Candidate: { relation: (null) ? [{ id: null }] : [] }
  }
}) }}
